// Normalize Telegram payload + parse commands/session id
const msg = $json.message || {};
const textRaw = msg.text ?? msg.caption ?? '';
const text = String(textRaw || '').trim();
const chatId = String(msg.chat?.id ?? msg.from?.id ?? '');
const fromId = String(msg.from?.id ?? '');
const messageId = String(msg.message_id ?? '');
const replyTo = msg.reply_to_message || null;
const replyToMessageId = String(replyTo?.message_id ?? '');
const replyToText = String(replyTo?.text ?? replyTo?.caption ?? '').trim();

// command parsing
let cmd = '';
let args = '';
if (text.startsWith('/')) {
  const m = text.match(/^\/([a-zA-Z0-9_]+)\s*(.*)$/s);
  if (m) { cmd = (m[1] || '').toLowerCase(); args = (m[2] || '').trim(); }
}

function extractSession(str) {
  if (!str) return '';
  let m = String(str).match(/Session:\s*(S[0-9A-Z]{6,12})/i);
  if (m) return m[1].toUpperCase();
  m = String(str).match(/(?:^|\s)#?(S[0-9A-Z]{6,12})(?:\s|$)/);
  if (m) return m[1].toUpperCase();
  return '';
}

let sessionId = '';
let userText = text;

// /s <sessionId> <text>
if (cmd === 's' || cmd === 'session') {
  const m = args.match(/^(S[0-9A-Z]{6,12})\s*(.*)$/s);
  if (m) {
    sessionId = m[1].toUpperCase();
    userText = (m[2] || '').trim();
  } else {
    userText = '';
  }
} else if (cmd === 'new') {
  userText = args;
} else {
  // allow prefix "#SXXXXXX text" or "SXXXXXX: text"
  const m = text.match(/^(?:#)?(S[0-9A-Z]{6,12})[:\s]+(.*)$/s);
  if (m) { sessionId = m[1].toUpperCase(); userText = (m[2] || '').trim(); }
}

// if reply contains session marker, use it (fallback)
if (!sessionId) sessionId = extractSession(replyToText);

return [{
  json: {
    chatId,
    fromId,
    messageId,
    replyToMessageId,
    replyToText,
    text,
    cmd,
    args,
    sessionId,
    userText,
  }
}];

// Session store in workflow static data (global) keyed by sessionId.
// No Wait node: conversation continues across separate executions.
// Parallel sessions supported by sessionId isolation.
const now = new Date().toISOString();
const input = $json;

function newSessionId() {
  const ts = Date.now().toString(36).toUpperCase().slice(-6);
  const rnd = Math.random().toString(36).slice(2,4).toUpperCase();
  return `S${ts}${rnd}`; // S + 8 chars
}

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};            // { [sessionId]: {chatId,status,memory,history,pending,createdAt,updatedAt} }
store.defaultByChat = store.defaultByChat || {};  // { [chatId]: sessionId }
store.pendingByMsg = store.pendingByMsg || {};    // { [questionMsgId]: sessionId }

// 1) Resolve sessionId from reply to our question (by Telegram message_id)
let sessionId = input.sessionId || '';
if (!sessionId && input.replyToMessageId && store.pendingByMsg[String(input.replyToMessageId)]) {
  sessionId = String(store.pendingByMsg[String(input.replyToMessageId)]);
}

// 2) Determine action
let action = 'RUN'; // HELP | LIST | SWITCH_ONLY | BUSY | RUN
let setDefault = false;
let userText = input.userText || '';

if (input.cmd === 'help' || input.cmd === 'start') {
  action = 'HELP';
} else if (input.cmd === 'list') {
  action = 'LIST';
} else if (input.cmd === 'new') {
  sessionId = newSessionId();
  setDefault = true;
  action = userText ? 'RUN' : 'SWITCH_ONLY';
} else if (input.cmd === 's' || input.cmd === 'session') {
  // sessionId already parsed in Parse Telegram
  setDefault = true;
  action = userText ? 'RUN' : 'SWITCH_ONLY';
} else {
  if (!sessionId) {
    const def = store.defaultByChat[String(input.chatId)];
    if (def) sessionId = String(def);
  }
  if (!sessionId) {
    sessionId = newSessionId();
    setDefault = true;
  }
  action = userText ? 'RUN' : 'SWITCH_ONLY';
}

// 3) Ensure session exists
if (sessionId) {
  const sid = String(sessionId);
  if (!store.sessions[sid]) {
    store.sessions[sid] = {
      sessionId: sid,
      chatId: String(input.chatId),
      status: 'IDLE',
      memory: '',
      history: [],
      pending: null, // {question, questionMsgId, askedAt}
      createdAt: now,
      updatedAt: now,
    };
  } else {
    store.sessions[sid].chatId = String(input.chatId);
    store.sessions[sid].updatedAt = now;
  }
  if (setDefault) store.defaultByChat[String(input.chatId)] = sid;

  const sess = store.sessions[sid];
  // Busy guard: if a task is running, don't start another in the same session
  if (sess?.status === 'RUNNING' && action === 'RUN') action = 'BUSY';

  // If session is WAITING but user sent something, it's their answer; allow RUN.
  // (No special branch needed.)
}

return [{
  json: {
    ...input,
    sessionId: sessionId || '',
    userText,
    action,
    setDefault,
    session: sessionId ? store.sessions[String(sessionId)] : null,
  }
}];

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const chatId = String($json.chatId);
const rows = Object.values(store.sessions).filter(s => String(s.chatId) === chatId);
rows.sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));

let out = "📌 *Сессии:*\\n\\n";
if (!rows.length) out += "Пока нет сессий. Напиши /new чтобы создать.";
else {
  const def = (store.defaultByChat || {})[chatId] || '';
  for (const s of rows) {
    const isDef = (def && s.sessionId === def) ? " _(default)_" : "";
    out += `• \\`${s.sessionId}\\` — *${s.status || 'IDLE'}*${isDef}\\n`;
  }
  out += "\\nПисать в сессию: `/s SESSION_ID текст`";
}
return [{json:{...$json, listText: out}}];

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.pendingByMsg = store.pendingByMsg || {};
const sid = String($json.sessionId);
const now = new Date().toISOString();

const sess = store.sessions[sid] || {sessionId:sid, chatId:String($json.chatId), status:'IDLE', memory:'', history:[], pending:null, createdAt:now, updatedAt:now};

// If we were waiting for an answer, clear pending mapping now
if (sess.pending?.questionMsgId) {
  delete store.pendingByMsg[String(sess.pending.questionMsgId)];
  sess.pending = null;
}

sess.status = 'RUNNING';
sess.updatedAt = now;
sess.chatId = String($json.chatId);
sess.history = Array.isArray(sess.history) ? sess.history : [];

if ($json.userText) {
  sess.history.push({role:'user', at: now, content: String($json.userText).slice(0, 4000)});
}
if (sess.history.length > 30) sess.history = sess.history.slice(-30);

store.sessions[sid] = sess;

return [{json:{...$json, session: sess, turn: Number($json.turn||0)}}];

const sid = String($json.sessionId);
const sess = $json.session || {};
const memory = String(sess.memory || '').trim();

const history = Array.isArray(sess.history) ? sess.history : [];
const last = history.slice(-12);

let histText = '';
for (const h of last) {
  const role = h.role === 'assistant' ? 'Assistant' : 'User';
  const c = String(h.content || '').replace(/\r/g,'').trim();
  if (!c) continue;
  histText += `${role}: ${c}\n`;
}

const turn = Number($json.turn || 0);

return [{
  json: {
    ...$json,
    memory,
    historyText: histText.trim(),
    turn,
  }
}];

parameters.text:
=Ты автономный AI-агент, который выполняет задачи пользователя в рамках Telegram-сессии.

Session: {{ $json.sessionId }}
ChatId: {{ $json.chatId }}

ПАМЯТЬ (summary, обновляй в поле new_memory):
{{ $json.memory || "(пусто)" }}

ПОСЛЕДНИЕ СООБЩЕНИЯ (контекст):
{{ $json.historyText || "(нет)" }}

ТЕКУЩИЙ ВХОД ОТ ПОЛЬЗОВАТЕЛЯ:
{{ $json.userText }}

Правила:
1) Выполняй задачу, используя доступные tools.
2) Если для продолжения нужны данные от пользователя — задай ОДИН конкретный вопрос.
3) Ответ ВСЕГДА строго одним JSON объектом, без лишнего текста.

Форматы ответа:

A) Нужно уточнение:
{"status":"NEED_USER","question":"...","new_memory":"..."}

B) Готово:
{"status":"DONE","final_message":"...","comments":"...","new_memory":"..."}

C) Продолжай без пользователя (редко):
{"status":"CONTINUE","note":"...","new_memory":"..."}

