// Parse Agent Output (for MERGE output) - no $node[] usage

const now = new Date().toISOString();
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

const sid = String($json.sessionId || '').trim();
const chatId = String($json.chatId || '').trim();
const userText = String($json.userText || '').trim();

if (!sid) {
  return [{ json: { agent: { status: 'NEED_USER', question: 'Не найден sessionId.' } } }];
}

// agent raw output is here:
const raw = String($json.output || '').trim();

let out = null;
try { out = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { out = JSON.parse(m[0]); } catch (e2) {} }
}
if (!out || typeof out !== 'object') out = { status: 'DONE', final_message: raw || 'Готово.', comments: '', new_memory: '' };

const status = String(out.status || '').toUpperCase().trim() || 'DONE';
const question = String(out.question || '').trim();
const final_message = String(out.final_message || '').trim();
const comments = String(out.comments || out.note || '').trim();
let new_memory = String(out.new_memory || '').trim();

// session save (минимально)
const sess = store.sessions[sid] || { sessionId: sid, chatId, memory: '', history: [], createdAt: now, updatedAt: now };
const prevMemory = String(sess.memory || '').trim();
const userLast = userText.slice(0, 300);

if (!new_memory) {
  if (status === 'NEED_USER' && question) new_memory = `WAITING: ${question}${userLast ? ` | USER_LAST: ${userLast}` : ''}`;
  else if (status === 'DONE' && (final_message || comments)) new_memory = `DONE: ${final_message || comments}`;
  else new_memory = prevMemory;
}
if (!new_memory) new_memory = `SESSION: ${sid} | updatedAt: ${now}`;

sess.memory = new_memory;
sess.updatedAt = now;
sess.chatId = chatId || sess.chatId;

sess.history = Array.isArray(sess.history) ? sess.history : [];
if (sess.history.length > 10) sess.history = sess.history.slice(-10);
store.sessions[sid] = sess;

// ВАЖНО: возвращаем только маленький json (не spread $json)
return [{
  json: {
    sessionId: sid,
    chatId,
    userText,
    session: sess,
    agent: { status, question, final_message, comments, new_memory }
  }
}];

