// Save pending question into session + mapping by Telegram message id
// IMPORTANT: do NOT read $node["Parse Agent Output"].json (can be huge). Use current input only.

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.pendingByMsg = store.pendingByMsg || {};

const sid = String($json.sessionId);
const now = new Date().toISOString();

// telegram sendMessage output is current $json (this node input)
const sent = $json;
const msgId = String(sent.message_id || sent.result?.message_id || '');

// question text should be already in $json.agent.question (from Parse Agent Output)
const question = String($json.agent?.question || '').trim() || 'Нужны данные для продолжения.';

// make sure session exists
const sess = store.sessions[sid] || {
  sessionId: sid,
  chatId: String($json.chatId),
  status: 'IDLE',
  memory: '',
  history: [],
  pending: null,
  createdAt: now,
  updatedAt: now,
};

sess.status = 'WAITING';
sess.updatedAt = now;
sess.chatId = String($json.chatId);
sess.pending = { question, questionMsgId: msgId, askedAt: now };

// history: keep small
sess.history = Array.isArray(sess.history) ? sess.history : [];
sess.history.push({ role: 'assistant', at: now, content: `QUESTION: ${question}` });
if (sess.history.length > 20) sess.history = sess.history.slice(-20);

store.sessions[sid] = sess;

// pending mapping: keep bounded
if (msgId) store.pendingByMsg[msgId] = sid;
const keys = Object.keys(store.pendingByMsg);
if (keys.length > 300) {
  // drop oldest-looking keys by insertion order approximation
  for (let i = 0; i < keys.length - 300; i++) delete store.pendingByMsg[keys[i]];
}

// also cap session count to avoid huge static data
const sids = Object.keys(store.sessions);
if (sids.length > 200) {
  // delete oldest by updatedAt
  const arr = sids
    .map(k => ({ k, t: Date.parse(store.sessions[k]?.updatedAt || store.sessions[k]?.createdAt || now) || 0 }))
    .sort((a, b) => a.t - b.t);
  for (let i = 0; i < arr.length - 200; i++) delete store.sessions[arr[i].k];
}

return [{ json: { ok: true, sessionId: sid, questionMsgId: msgId } }];

