const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.pendingByMsg = store.pendingByMsg || {};
const sid = String($json.sessionId);
const now = new Date().toISOString();

const sess = store.sessions[sid];
if (sess) {
  if (sess.pending?.questionMsgId) delete store.pendingByMsg[String(sess.pending.questionMsgId)];
  sess.pending = null;
  sess.status = 'IDLE';
  sess.updatedAt = now;
}
return [{json:$json}];

const maxAuto = 5;
const turn = Number($json.turn || 0);

if (turn >= maxAuto) {
  // force user interaction to avoid endless loop
  return [{
    json: {
      ...$json,
      agent: { status: 'NEED_USER', question: 'Я сделал несколько автоматических шагов. Нужно твоё подтверждение/данные, чтобы продолжать. Что дальше?', final_message:'', comments:'', new_memory: $json.session?.memory || $json.memory || '' }
    }
  }];
}

return [{
  json: {
    ...$json,
    turn: turn + 1,
    userText: '(continue)'
  }
}];
